package com.lumora.sms.security.handler;
import com.lumora.sms.security.audit.SecurityAuditService; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import java.io.IOException;
/** Returns a safe 403 response and audits the rejected authenticated request. */
@Component @RequiredArgsConstructor public class LumoraAccessDeniedHandler implements AccessDeniedHandler { private final SecurityAuditService audit; public void handle(HttpServletRequest req,HttpServletResponse res,AccessDeniedException ex)throws IOException,ServletException{if(req.getUserPrincipal()!=null)audit.record(req.getUserPrincipal().getName(),"ACCESS_DENIED",req.getRemoteAddr());res.sendError(HttpServletResponse.SC_FORBIDDEN,"You are not authorized to access this resource.");} }
